--
-- Table structure for table `consumo_turno`
--

DROP TABLE IF EXISTS `consumo_turno`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `consumo_turno` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `turno` tinyint unsigned NOT NULL,
  `operario` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cons_entrada_ap_principal_6in` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_fria_lavanderia_4in` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_lab_lavanderia` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_fria_tintoreria_4in` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_rotativa_3in` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_tintoreria_6in` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_ptar2_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_puerta2_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_puerta4_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_puerta5_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_puerta6_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_puerta7_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_caldera_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_quimicos` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_lavanderia_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ap_zona_lodos_acueducto` decimal(10,2) DEFAULT NULL,
  `cons_entrada_medidor_rojo_tintoreria` decimal(10,2) DEFAULT NULL,
  `cons_entrada_medidor_rojo_lavanderia` decimal(10,2) DEFAULT NULL,
  `cons_rama` decimal(10,2) DEFAULT NULL,
  `cons_abridora_1` decimal(10,2) DEFAULT NULL,
  `cons_abridora_2` decimal(10,2) DEFAULT NULL,
  `cons_agua_caliente_tintoreria` decimal(10,2) DEFAULT NULL,
  `cons_medidor_prueba_agua_caliente` decimal(10,2) DEFAULT NULL,
  `cons_tanque_reuso_2in` decimal(10,2) DEFAULT NULL,
  `cons_ptar` decimal(10,2) DEFAULT NULL,
  `cons_envio_th` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ro1` decimal(10,2) DEFAULT NULL,
  `cons_salida_ro1` decimal(10,2) DEFAULT NULL,
  `cons_entrada_ro2` decimal(10,2) DEFAULT NULL,
  `cons_salida_ro2` decimal(10,2) DEFAULT NULL,
  `cons_mbr1` decimal(10,2) DEFAULT NULL,
  `cons_mbr2` decimal(10,2) DEFAULT NULL,
  `cons_ingreso_uf_ptap` decimal(10,2) DEFAULT NULL,
  `cons_salida_uf_ptap` decimal(10,2) DEFAULT NULL,
  `cons_medidor_verde_retorno` decimal(10,2) DEFAULT NULL,
  `cons_total_produccion_m3` decimal(10,2) DEFAULT NULL COMMENT 'Consumo total produccion (tintoreria + lavanderia)',
  `cons_tintoreria_m3` decimal(10,2) DEFAULT NULL,
  `cons_lavanderia_m3` decimal(10,2) DEFAULT NULL,
  `kg_tintoreria` decimal(10,2) DEFAULT NULL,
  `unidades_lavanderia` decimal(10,2) DEFAULT NULL,
  `indicador_tintoreria_l_kg` decimal(10,4) DEFAULT NULL COMMENT 'L/kg tela',
  `indicador_lavanderia_l_und` decimal(10,4) DEFAULT NULL COMMENT 'L/unidad efectiva',
  `rollover_detectado` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 si algun contador bajo respecto al turno anterior',
  `notas` text COLLATE utf8mb4_unicode_ci,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_consumo_fecha_turno` (`fecha`,`turno`),
  KEY `idx_consumo_fecha` (`fecha`),
  CONSTRAINT `chk_consumo_turno` CHECK ((`turno` in (1,2,3)))
) ENGINE=InnoDB AUTO_INCREMENT=2527 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Consumos calculados por turno (delta de lecturas acumuladas) + KPIs operativos';
/*!40101 SET character_set_client = @saved_cs_client */;

